// ✅ รับ item แรกจาก Webhook
const item = $input.first() || { json: {}, binary: {} };
const headers = item.json.headers || {};

// ✅ ดึง Authorization header (รองรับทั้งตัวเล็ก/ใหญ่)
const authHeader = headers.authorization || headers.Authorization;

// ✅ ยก prompt จาก body มาไว้บนสุด (จะได้เรียกใช้ {{$json.prompt}} ได้ทุกที่)
const prompt = (item.json.body?.prompt ?? "").toString().trim();

// ✅ หา field ชื่อ binary อัตโนมัติ (เช่น "data" หรือ "image")
const binaryField = Object.keys(item.binary || {})[0] || null;

// ❗ ถ้าไม่ส่ง Authorization มา → ตอบ error แต่ยังพก binary ต่อให้ด้วย
if (!authHeader) {
  return [{
    json: {
      success: false,
      status: 401,
      message: 'หา Authorization header ไม่เจอ',
      prompt,       // เผื่ออยากตรวจในภายหลัง
      binaryField,  // บอกชื่อฟิลด์ binary ที่แนบมา
    },
    binary: item.binary, // สำคัญ! พกไฟล์ภาพต่อ
  }];
}

// ✂️ ตัดคำว่า Bearer ออก แล้ว trim
const key = authHeader.replace(/^Bearer\s+/i, "").trim();

// ✅ คืนค่า key + prompt + binaryField และพก binary ต่อ
return [{
  json: {
    success: true,
    key,
    prompt,       // ใช้ต่อใน node ถัดไป: {{ $json.prompt }}
    binaryField,  // ใช้ตั้งค่า Binary property ในโมเดลภาพ ถ้าต้อง
  },
  binary: item.binary, // สำคัญ! พกไฟล์ภาพต่อ
}];

// ✅ รับข้อมูลจาก node ก่อนหน้า (Google Sheet)
const item = $input.first();
const row = item.json || {};
const key = $json.key || row.api_key; // เผื่อรับ key จาก node ก่อนหน้า

// ✅ ตัวแปรพื้นฐาน
let success = false;
let message = "";
let reason = "";

// ✅ ตรวจสอบว่าพบข้อมูลในชีตหรือไม่
if (!row.api_key) {
  success = false;
  message = "ไม่พบ API key ในระบบ";
  reason = "not_found";
}

// ✅ ตรวจสอบว่า key ตรงกันไหม
else if (String(row.api_key).trim() !== String(key).trim()) {
  success = false;
  message = "API key ไม่ถูกต้อง";
  reason = "invalid_key";
}

// ✅ ตรวจสอบสถานะ active
else if (
  row.is_active === false ||
  row.is_active === "FALSE" ||
  row.is_active === "false" ||
  row.is_active === 0
) {
  success = false;
  message = "API key ถูกระงับการใช้งาน";
  reason = "inactive";
}

// ✅ ตรวจสอบจำนวนการใช้งาน (limit)
else {
  const used = Number(row.used || 0);
  const limit = Number(row.limit || 0);

  if (used >= limit) {
    success = false;
    message = `เกินจำนวนการใช้งานที่กำหนด (${limit} ครั้ง)`;
    reason = "limit_exceeded";
  } else {
    success = true;
    message = "ตรวจสอบสิทธิ์สำเร็จ สามารถใช้งานได้";
    reason = "ok";
  }
}

// ✅ สร้างผลลัพธ์เพื่อนำไปใช้งานต่อ
return [
  {
    json: {
      success,
      message,
      reason,
      current_used: row.used,
      current_limit: row.limit,
      date_last_used: row.date_last_used,
      key_checked: key,
      ...row,
    },
  },
];

