// 🧩 พรีเซ็ตข้อความ
const presetA = 'Make the image look like a professional studio portrait. Improve lighting, add soft shadows, enhance clarity and natural skin tones. Keep background clean and slightly blurred.';
const presetB = 'Transform the image into a fantasy-style scene. Add glowing particles, vibrant colors, and cinematic lighting. Maintain the main subject but change the atmosphere to magical or surreal.';
const presetC = 'Convert the image into an artistic painting style. Add brush texture, balanced tones, and enhance visual composition for a gallery-ready look.';

// 🧠 ฟังก์ชันเลือกข้อความพรีเซ็ต
function resolvePrompt(raw) {
  const t = String(raw ?? '').trim().toUpperCase();
  if (['A', '1', 'PROMPTA', 'PRESET1', 'แบบที่A', 'แบบที่1'].includes(t)) 
    return { prompt: presetA, type: 'A' };
  if (['B', '2', 'PROMPTB', 'PRESET2', 'แบบที่B', 'แบบที่2'].includes(t)) 
    return { prompt: presetB, type: 'B' };
  if (['C', '3', 'PROMPTC', 'PRESET3', 'แบบที่C', 'แบบที่3'].includes(t)) 
    return { prompt: presetC, type: 'C' };

  // 🆕 ถ้าไม่ตรงกับ A/B/C → ถือว่าเป็น D
  return { prompt: raw, type: 'CUSTOM' };
}

// 🧾 ดึงข้อมูลทั้งหมดจาก node ก่อนหน้า
const input = $input.all();

// 🔁 ประมวลผลแต่ละรายการ
return input.map(item => {
  const { prompt: finalPrompt, type: presetType } = resolvePrompt(item.json.prompt);

  return {
    json: {
      ...item.json,
      finalPrompt,
      presetType, // เพิ่มประเภทไว้ด้วย เช่น A/B/C/D
    },
    binary: item.binary, // ✅ ส่งต่อ binary เช่นภาพหรือไฟล์
  };
});

